mapper.select:
select
pod.line_no, pod.snap_item_name as item_name, pod.line_amount_excluding_tax,
pod.snap_unit_name as unit_name, pod.quantity, pod.snap_unit_price as unit_price
from purchase_order_line pod join purchase_order po on pod.po_id = po.po_id where pod.po_id = #{poId}
and po.purchaser_user_id = #{userId}
order by pod.line_no asc
